  public getDefaultRuleFilter({ ruleIds, ruleType, ruleDomain }) {
    const defaultRuleFilter: any = {
      ruleType,
      activeFr: { $lte: moment(new Date()).utc().toISOString() },
      activeTo: { $gte: moment(new Date()).utc().toISOString() },
      ruleAction: { $ne: RULE_ACTION.QUERY },
      isActive: true,
      isDelete: false,
      status: RULE_STATUS.ACTIVATED
    };
    if (ruleIds && Array.isArray(ruleIds)) {
      defaultRuleFilter._id = { $in: FunctionHelper.convertToMongoId(ruleIds) };
    } else {
      if (ruleDomain) {
        defaultRuleFilter.$or = [{ domain: ruleDomain }, { domainCode: ruleDomain }];
      }
    }
    return defaultRuleFilter;

